#!/usr/bin/env node
// Outreach Desk update 1: demo-link rule, agreement + invoice documents, your details in settings.
// Run from the project folder:  node update-1.mjs        (add --force to overwrite files you edited yourself)
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const FILES = [{"path": "src/lib/shared/catalog.js", "before": "7aa151929da961bc6578da3426471541aa98f9e5008b7c395ab999f029dbbf10", "after": "7ce7112821077b3189ad49fa6d90f17f4e15c14281bf5de852dcd0ec95b7290d", "b64": ""}, {"path": "src/lib/server/db.js", "before": "bf09eb217663700daccf8fa485f5eb40d896812925160d4ea8081aac10c336ec", "after": "863ad01547abf9962ac2ac56d55f9c0e9880196193c0b29ea98941aaa5098558", "b64": ""}, {"path": "src/lib/server/actions.js", "before": "fd9975b1ad5c00fb015bb68817b32ac12d068816c29a24de2f29687d9f0dc380", "after": "9be3ca0b88a88faee9146d1eedbed08fe453c36d64e3b2c39a7d2ef762226996", "b64": ""}, {"path": "src/lib/server/discover.js", "before": "493780335e1ee199fe40921a7b65e6c0781cd98d314283b6a06f49cda11579d5", "after": "3be8141dc2d6045c8b8d216f26cf4caf4b86296d1348c5c9136a0d93ab865b41", "b64": ""}, {"path": "src/routes/api/settings/+server.js", "before": "9e3e3a8fb67bc33d78714398020aefda2543bcf94067ad821e8cfcc8386704ff", "after": "1cb8b4ae118ddbf8c45328ac661cc49cb6e111a8945acd55df200f2817eb70df", "b64": ""}, {"path": "src/routes/+layout.svelte", "before": "df01f51c679a462ee7926aacf68c4112fc37875352f41ea89bbeb670ac49eca0", "after": "3d47029b886d4048dd4a2277e4bdfb7df39ec72849b84e7e8862ac96431babcb", "b64": ""}, {"path": "src/routes/conversations/+page.svelte", "before": "ff8912c68185ee918d74a2d3ec18efce1d401a1e29e1c8fa2ba877f69fca2d19", "after": "e3fa253e282bf17cfde6c89466e6ed5063800be70f34b26a1788e12a6a94afaf", "b64": ""}, {"path": "src/routes/discover/+page.svelte", "before": "418f62b6d393742af255921cec89afef103411ff291e5ccc8e28bc7937fa8c9a", "after": "dbdea693adc927958a4c070379f7bcd2f71603ca8195601620f48774a4d22e8f", "b64": ""}, {"path": "src/routes/pricing/+page.svelte", "before": "53ff281103954c9ab5a9dcf1aedcb516890f6c58dbb242790d10efcdb4660c7c", "after": "1b8acdc01d5e38bb91986a4d61fe50d6de3c147bac49a4f2f903fa1856878c8e", "b64": ""}, {"path": "scripts/test.js", "before": "59f57a80be558e4663ca285e03df978cada14cbedd7136bc34b40ef26eae65b6", "after": "3b644b123de084ac62438ff3e6d2c3bfb1174194d5d07e304153083fb2865b1b", "b64": ""}, {"path": "src/lib/shared/documents.js", "before": null, "after": "1241850a92dba2a341379689015bf74d1b190ad3159ac9793007021d821ae716", "b64": ""}, {"path": "src/routes/documents/[type]/[id]/+page.server.js", "before": null, "after": "14c18e0a35b49bbd18149f214193f59caef3458fde0157778a2ed21c797c7fc4", "b64": ""}, {"path": "src/routes/documents/[type]/[id]/+page.svelte", "before": null, "after": "ed52db7505358b58889c9192418ac05aa9f59fb9523496f1d50de8a34c2b2b08", "b64": ""}];
const force = process.argv.includes('--force');
const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');

if (!fs.existsSync('package.json') || !JSON.parse(fs.readFileSync('package.json', 'utf8')).name?.includes('outreach-desk')) {
  console.error('Run this from the outreach-desk project folder (the one with package.json).');
  process.exit(1);
}

// 1. Check first, write later, so a half-applied update can never happen.
const edited = [];
for (const f of FILES) {
  if (!fs.existsSync(f.path)) continue;
  const now = sha(fs.readFileSync(f.path));
  if (now !== f.before && now !== f.after && f.before !== null) edited.push(f.path);
}
if (edited.length && !force) {
  console.error('These files differ from the version this update expects, so you may have edited them:');
  edited.forEach((p) => console.error('  - ' + p));
  console.error('Nothing was changed. Run again with --force to overwrite them (a backup of each is kept).');
  process.exit(1);
}

// 2. Write, keeping a backup of anything that is replaced.
let written = 0, same = 0;
for (const f of FILES) {
  const data = Buffer.from(f.b64, 'base64');
  if (fs.existsSync(f.path)) {
    if (sha(fs.readFileSync(f.path)) === f.after) { same++; continue; }
    const bak = f.path + '.bak-before-update1';
    if (!fs.existsSync(bak)) fs.copyFileSync(f.path, bak);
  } else {
    fs.mkdirSync(path.dirname(f.path), { recursive: true });
  }
  fs.writeFileSync(f.path, data);
  written++;
  console.log('  wrote', f.path);
}
console.log(`\nDone: ${written} files written, ${same} already up to date.`);
console.log('Next: stop the app, then start it again (npm run dev). The database upgrades itself on start.');
